      if (ts.isNewExpression(node) && node.expression.getText(parsed) === "URL" && node.arguments?.[0] && ts.isStringLiteral(node.arguments[0])) expected.push(node.arguments[0].text);
      ts.forEachChild(node, visit);
    };
    visit(parsed);
